sp_instance.widget_parameters:
{
	"html": {
		"value": "<style>
.cc-hero {
    position: relative;
    overflow: hidden;
    padding: 70px 55px;
    min-height: 430px;
    background: linear-gradient(135deg, #0b1f3a 0%, #123d63 55%, #176b87 100%);
    color: #ffffff;
    font-family: "Helvetica Neue", Arial, sans-serif;
}

.cc-hero:before,
.cc-hero:after {
    content: "";
    position: absolute;
    border-radius: 50%;
    background: rgba(255,255,255,0.06);
}

.cc-hero:before {
    width: 360px;
    height: 360px;
    right: -100px;
    top: -120px;
}

.cc-hero:after {
    width: 240px;
    height: 240px;
    right: 120px;
    bottom: -150px;
}

.cc-hero-content {
    position: relative;
    z-index: 2;
    max-width: 850px;
}

.cc-hero-badge {
    display: inline-block;
    padding: 8px 16px;
    border: 1px solid rgba(255,255,255,0.25);
    border-radius: 30px;
    background: rgba(255,255,255,0.10);
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 0.5px;
    margin-bottom: 22px;
}

.cc-hero-badge .glyphicon {
    margin-right: 7px;
}

.cc-hero-title {
    margin: 0 0 18px;
    font-size: 46px;
    line-height: 1.12;
    font-weight: 700;
    letter-spacing: -0.8px;
}

.cc-hero-title span {
    color: #72d6e8;
}

.cc-hero-text {
    max-width: 720px;
    margin: 0 0 28px;
    font-size: 18px;
    line-height: 1.7;
    color: rgba(255,255,255,0.88);
}

.cc-hero-actions {
    margin-top: 25px;
}

.cc-hero-btn {
    display: inline-block;
    padding: 13px 22px;
    margin-right: 10px;
    margin-bottom: 10px;
    border-radius: 7px;
    text-decoration: none !important;
    font-size: 15px;
    font-weight: 600;
    transition: all 0.2s ease;
}

.cc-hero-primary {
    background: #ffffff;
    color: #0b1f3a !important;
}

.cc-hero-secondary {
    border: 1px solid rgba(255,255,255,0.35);
    color: #ffffff !important;
    background: rgba(255,255,255,0.08);
}

.cc-hero-btn .glyphicon {
    margin-right: 8px;
}

.cc-hero-primary:hover,
.cc-hero-secondary:hover {
    transform: translateY(-2px);
}

.cc-hero-trust {
    margin-top: 32px;
    font-size: 13px;
    color: rgba(255,255,255,0.72);
}

.cc-hero-trust span {
    margin-right: 22px;
}

.cc-hero-trust .glyphicon {
    margin-right: 6px;
    color: #72d6e8;
}

@media (max-width: 767px) {
    .cc-hero {
        padding: 45px 25px;
    }

    .cc-hero-title {
        font-size: 34px;
    }

    .cc-hero-text {
        font-size: 16px;
    }
}
</style>
<section class="cc-hero">
<div class="cc-hero-content">
<div class="cc-hero-badge">Verified Campus Opportunity Ecosystem</div>
<h1 class="cc-hero-title">Discover. Connect. Collaborate.</h1>
<p class="cc-hero-text">Campus Connect brings verified events, student collaboration, skill-based teammate matching and mentor guidance together in one trusted ServiceNow platform.</p>
<div class="cc-hero-actions"><a class="cc-hero-btn cc-hero-primary" href="?id=find_teammates"> Find Teammates </a> <a class="cc-hero-btn cc-hero-secondary" href="#campus-connect-features"> Explore Campus Connect </a></div>
<div class="cc-hero-trust">Verified Events Smart Skill Matching Mentor Connect</div>
</div>
</section>",
